1	import type { Step } from "@runlog/rules-schema";
2	
3	/**
4	 * What a deck may press, right now, in the pack's own words.
5	 *
6	 * The same reasoning as `snapshot.asks`: only a device holding the pack
7	 * and the log can say what is on offer, so it is published rather than
8	 * worked out by the server. Wider than `asks`, because a deck is the
9	 * owner pressing and may do what the page's own buttons do.
10	 *
11	 * Deliberately conservative, for the reason `handsFree.ts` gives: this
12	 * removes ceremony, never a decision. Anything the player is genuinely
13	 * being asked, anything owed, and anything typed stops here and says so.
14	 */
15	export interface Offer {
16	  seq: number;
17	  primary: { id: "roll" | "carry-on" | "close" | "enter"; label: string; kind: string } | null;
18	  moves: Array<{ id: string; label: string }>;
19	  undo: { what: string } | null;
20	  /** Why a deck cannot press this, in words a key face can carry. */
21	  needsPage: string | null;
22	  presets: Array<{ kind: string; label: string; suggestions?: string[] }>;
23	}
24	
25	export interface OfferInput {
26	  /** The snapshot this offer belongs to; a press carries it back. */
27	  seq: number;
28	  /** Active, editable, and actually started. */
29	  live: boolean;
30	  /** Nothing more is being asked of this step. */
31	  settled: boolean;
32	  step: Step | null;
33	  stepLabel: string | null;
34	  moves: Array<{ id: string; label: string }>;
35	  canUndo: boolean;
36	  lastResult: string | null;
37	  /** Obligations standing in the way. */
38	  owed: number;
39	  /** What the run would suggest for a subject, where it suggests anything. */
40	  suggestions: string[];
41	}
42	
43	/** Steps a key can answer with one press, because they ask nothing first. */
44	const PRESSABLE: Record<string, "roll" | "carry-on" | "close" | "enter"> = {
45	  rollTable: "roll",
46	  finalizeUnit: "close",
47	};
48	
49	/** Steps that take something typed, and the preset that covers each. */
50	const TYPED = new Set(["declareSubject"]);
51	
52	export function offerOf(input: OfferInput): Offer {
53	  const moves = input.moves;
54	  const undo = input.canUndo && input.lastResult ? { what: input.lastResult } : null;
55	  const bare = { seq: input.seq, moves, undo, presets: [] as Offer["presets"] };
56	
57	  if (!input.live) return { ...bare, primary: null, needsPage: "Open the run on the page" };
58	  if (!input.step) return { ...bare, primary: null, needsPage: null };
59	
60	  const step = input.step;
61	  const kind = step.kind;
62	  const label = input.stepLabel ?? "";
63	
64	  // An unsettled step is still being asked something, the same reasoning
65	  // `closesTheUnit` uses to refuse an unsettled unit: it is not yet a bare
66	  // press for a key to make.
67	  if (!input.settled) return { ...bare, primary: null, needsPage: `${label} on the page` };
68	
69	  if (TYPED.has(kind))
70	    return {
71	      ...bare,
72	      primary: null,
73	      needsPage: `${label} on the page`,
74	      presets: [{ kind, label, ...(input.suggestions.length > 0 ? { suggestions: input.suggestions } : {}) }],
75	    };
76	
77	  // A manual step asks nothing on its own; it only asks something when it
78	  // carries a checklist to confirm. Empty, it is as bare a press as a roll.
79	  if (step.kind === "manual") {
