1	import { describe, expect, it } from "vitest";
2	import {
3	  backoffMs,
4	  openLive,
5	  parseChanged,
6	  parseDrive,
7	  parseGesture,
8	  socketUrl,
9	  type Changed,
10	  type Drive,
11	  type Gesture,
12	} from "./socket.ts";
13	
14	/**
15	 * A pretend socket: opened, closed and spoken to by the test, so the
16	 * reconnect and re-watch can be watched without a network.
17	 */
18	class FakeSocket {
19	  static all: FakeSocket[] = [];
20	  sent: string[] = [];
21	  closed = false;
22	  onopen: (() => void) | null = null;
23	  onmessage: ((e: { data: unknown }) => void) | null = null;
24	  onclose: (() => void) | null = null;
25	  onerror: (() => void) | null = null;
26	  constructor(public url: string) {
27	    FakeSocket.all.push(this);
28	  }
29	  send(data: string) {
30	    this.sent.push(data);
31	  }
32	  close() {
33	    this.closed = true;
34	    this.onclose?.();
35	  }
36	}
37	
38	/** Waits that a test releases by hand, in order. */
39	function manualClock() {
40	  const pending: Array<{ ms: number; fn: () => void }> = [];
41	  return {
42	    pending,
43	    wait: (ms: number, fn: () => void) => {
44	      const entry = { ms, fn };
45	      pending.push(entry);
46	      return () => {
47	        const i = pending.indexOf(entry);
48	        if (i >= 0) pending.splice(i, 1);
49	      };
50	    },
51	    fire() {
52	      const next = pending.shift();
53	      next?.fn();
54	    },
55	  };
56	}
57	
58	const tick = () => new Promise((r) => setTimeout(r, 0));
59	
60	describe("the address", () => {
61	  it("is the API's base with /api swapped for /ws, over wss, the token in the query", () => {
62	    expect(socketUrl("https://runlog.example/api", "tok")).toBe("wss://runlog.example/ws?token=tok");
63	    expect(socketUrl("https://runlog.example/some/path/api/", "tok")).toBe("wss://runlog.example/some/path/ws?token=tok");
64	    expect(socketUrl("http://localhost:5173/api", "tok")).toBe("ws://localhost:5173/ws?token=tok");
65	  });
66	});
67	
68	describe("the backoff", () => {
69	  it("doubles from a second and stops at half a minute", () => {
70	    const flat = () => 0.5;
71	    expect(backoffMs(0, flat)).toBe(1000);
72	    expect(backoffMs(1, flat)).toBe(2000);
73	    expect(backoffMs(3, flat)).toBe(8000);
74	    expect(backoffMs(10, flat)).toBe(30_000);
75	  });
76	});
77	
78	describe("what comes down", () => {
79	  it("shapes a gesture and refuses what is not one", () => {
80	    expect(parseGesture(JSON.stringify({ t: "gesture", id: "s1", kind: "rolled", at: "x" }))).toEqual({
81	      t: "gesture",
82	      id: "s1",
83	      kind: "rolled",
84	      data: {},
85	      at: "x",
86	    });
87	    expect(parseGesture(JSON.stringify({ t: "gesture", id: "s1" }))).toBeNull();
88	    expect(parseGesture(JSON.stringify({ t: "changed", id: "s1", seq: 1 }))).toBeNull();
89	  });
90	
91	  it("understands one shape and ignores the rest", () => {
92	    expect(parseChanged(JSON.stringify({ t: "changed", id: "s1", seq: 4 }))).toEqual({ t: "changed", id: "s1", seq: 4 });
93	    expect(parseChanged(JSON.stringify({ t: "hello" }))).toBeNull();
94	    expect(parseChanged("not json")).toBeNull();
95	    expect(parseChanged(new ArrayBuffer(2))).toBeNull();
96	  });
97	
98	  it("shapes a drive and refuses what is not one", () => {
99	    expect(parseDrive(JSON.stringify({ t: "drive", from: "d1", run: "s1", seq: 3, ref: "r1", press: "primary" }))).toEqual({
100	      t: "drive",
101	      from: "d1",
102	      run: "s1",
103	      seq: 3,
104	      ref: "r1",
105	      press: "primary",
106	    });
107	    expect(parseDrive(JSON.stringify({ t: "drive", from: "d1", run: "s1", seq: 3, ref: "r1", press: "move", move: "salvage" }))).toEqual({
108	      t: "drive",
109	      from: "d1",
110	      run: "s1",
111	      seq: 3,
112	      ref: "r1",
113	      press: "move",
114	      move: "salvage",
115	    });
116	    expect(
117	      parseDrive(JSON.stringify({ t: "drive", from: "d1", run: "s1", seq: 3, ref: "r1", press: "answer", answer: { subject: "bowl" } })),
118	    ).toEqual({ t: "drive", from: "d1", run: "s1", seq: 3, ref: "r1", press: "answer", answer: { subject: "bowl" } });
119	    expect(parseDrive(JSON.stringify({ t: "drive", from: "d1", run: "s1", ref: "r1", press: "primary" }))).toBeNull();
120	    expect(parseDrive(JSON.stringify({ t: "gesture", id: "s1", kind: "rolled", at: "x" }))).toBeNull();
121	    expect(parseDrive("not json")).toBeNull();
122	    expect(parseDrive(new ArrayBuffer(2))).toBeNull();
123	  });
124	});
125	
126	describe("the live socket", () => {
127	  it("connects with a fresh token, sends its watch on open, and hands over changes", async () => {
128	    FakeSocket.all = [];
129	    const clock = manualClock();
130	    const changes: Changed[] = [];
131	    const gestures: Gesture[] = [];
132	    const states: boolean[] = [];
133	    let tokens = 0;
134	    const live = openLive({
135	      url: async () => socketUrl("https://runlog.example/api", `t${++tokens}`),
136	      onChanged: (c) => changes.push(c),
137	      onGesture: (g) => gestures.push(g),
138	      onState: (s) => states.push(s),
139	      WebSocketImpl: FakeSocket as unknown as typeof WebSocket,
140	      wait: clock.wait,
141	    });
142	    live.watch("s1");
143	    await tick();
144	    const first = FakeSocket.all[0]!;
145	    expect(first.url).toBe("wss://runlog.example/ws?token=t1");
146	    expect(live.open).toBe(false);
147	    first.onopen?.();
148	    expect(live.open).toBe(true);
149	    expect(first.sent).toEqual([JSON.stringify({ t: "watch", id: "s1" })]);
150	    first.onmessage?.({ data: JSON.stringify({ t: "changed", id: "s1", seq: 9 }) });
151	    first.onmessage?.({ data: "noise" });
152	    expect(changes).toEqual([{ t: "changed", id: "s1", seq: 9 }]);
153	    // A gesture goes out only while the line is up, and comes in shaped.
154	    expect(live.gesture("s1", "rolled", { total: 14 })).toBe(true);
155	    expect(first.sent.at(-1)).toBe(JSON.stringify({ t: "gesture", id: "s1", kind: "rolled", data: { total: 14 } }));
156	    first.onmessage?.({
157	      data: JSON.stringify({ t: "gesture", id: "s1", kind: "rolled", data: { total: 3 }, from: "Mira", at: "2026-01-01T00:00:00Z" }),
158	    });
159	    expect(gestures).toEqual([{ t: "gesture", id: "s1", kind: "rolled", data: { total: 3 }, from: "Mira", at: "2026-01-01T00:00:00Z" }]);
160	
161	    // Switching runs sends the new watch at once.
162	    live.watch("s2");
163	    expect(first.sent.at(-1)).toBe(JSON.stringify({ t: "watch", id: "s2" }));
164	
165	    // The line drops: a reconnect is scheduled, with a new token, and the
166	    // watch is sent again on open.
167	    first.onclose?.();
168	    expect(live.open).toBe(false);
169	    expect(clock.pending).toHaveLength(1);
170	    clock.fire();
171	    await tick();
172	    const second = FakeSocket.all[1]!;
173	    expect(second.url).toBe("wss://runlog.example/ws?token=t2");
174	    second.onopen?.();
175	    expect(second.sent).toEqual([JSON.stringify({ t: "watch", id: "s2" })]);
176	    expect(states).toEqual([true, false, true]);
177	
178	    // Closed for good: no reconnect.
179	    live.close();
180	    expect(second.closed).toBe(true);
181	    expect(clock.pending).toHaveLength(0);
182	    expect(live.open).toBe(false);
183	  });
184	
185	  it("hands over a drive from a deck, and answers it back to the one that asked", async () => {
186	    FakeSocket.all = [];
187	    const clock = manualClock();
188	    const drives: Drive[] = [];
189	    const live = openLive({
190	      url: async () => socketUrl("https://runlog.example/api", "t1"),
191	      onChanged: () => {},
192	      onDrive: (d) => drives.push(d),
193	      WebSocketImpl: FakeSocket as unknown as typeof WebSocket,
194	      wait: clock.wait,
195	    });
